WITH demo_sales AS ( SELECT hd_bill.hd_demo_sk AS bill_demo_sk, hd_bill.hd_income_band_sk AS bill_income_band, hd_ship.hd_demo_sk AS ship_demo_sk, hd_ship.hd_income_band_sk AS ship_income_band, i.i_category, p.p_promo_name, cs.cs_order_number, cs.cs_quantity, cs.cs_net_profit, cs.cs_ext_discount_amt, cs.cs_ext_list_price, CASE WHEN hd_ship.hd_income_band_sk > hd_bill.hd_income_band_sk THEN 1 ELSE 0 END AS ship_higher_income FROM catalog_sales cs JOIN item i ON cs.cs_item_sk = i.i_item_sk JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk JOIN household_demographics hd_bill ON cs.cs_bill_hdemo_sk = hd_bill.hd_demo_sk JOIN household_demographics hd_ship ON cs.cs_ship_hdemo_sk = hd_ship.hd_demo_sk ) SELECT bill_income_band, ship_income_band, i_category, COUNT(DISTINCT cs_order_number) AS orders_count, SUM(cs_net_profit) AS total_net_profit, SUM(cs_quantity) AS total_quantity, AVG(CASE WHEN cs_ext_list_price = 0 THEN 0 ELSE cs_ext_discount_amt / cs_ext_list_price END) * 100 AS avg_discount_pct, SUM(CASE WHEN ship_higher_income = 1 THEN cs_net_profit ELSE 0 END) AS profit_when_ship_higher, DENSE_RANK() OVER (ORDER BY SUM(cs_net_profit) DESC) AS profit_rank FROM demo_sales GROUP BY bill_income_band, ship_income_band, i_category HAVING COUNT(*) > 10 ORDER BY profit_rank
